public class SafepointLoopingTrap {
    private static double sum = 0;

    public static void computeWithoutSafepoint() {
        // In older JVMs or uncounted loops, the JIT might omit safepoint checks,
        // causing a safepoint-reaching delay if a GC is requested concurrently.
        for (long i = 0; i < 1_000_000_000L; i++) {
            sum += Math.sqrt(i);
        }
    }

    public static void main(String[] args) {
        new Thread(SafepointLoopingTrap::computeWithoutSafepoint).start();
    }
}
